function G.L(key, ...)
    local language = G.Storage and G.Storage.settings and G.Storage.settings.language or "sv"
    local row = strings[key]
    local value = row and row[language == "en" and 2 or 1] or key
    if select("#", ...) > 0 then return string.format(value, ...) end
    return value
end
